use std::sync::mpsc::{channel, Sender, Receiver};
use std::thread;

fn s1(tx: Sender<i32>) {
    tx.send(1).unwrap();
}

fn r(rx: Receiver<i32>) {
    let _ = rx.recv().unwrap();
}

fn main() {
    let (tx, rx) = channel::<i32>();

    let h1 = thread::spawn(move || s1(tx));
    let h2 = thread::spawn(move || r(rx));

